import { build } from 'esbuild';
import { readFile, writeFile, mkdir, readdir, rm } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const directory = path.dirname(fileURLToPath(import.meta.url));
const output = path.resolve(directory, '../../assets/gallery');
await mkdir(output, { recursive: true });

// Only delete files generated by this build, never the artwork or font assets.
for (const name of await readdir(output)) {
  if (/^app-[A-Z0-9]+\.(js|css)(\.LEGAL\.txt)?$/.test(name)) {
    await rm(path.join(output, name));
  }
}

const result = await build({
  absWorkingDir: directory,
  entryPoints: { app: 'src/main.jsx' },
  outdir: output,
  entryNames: '[name]-[hash]',
  bundle: true,
  minify: true,
  target: 'es2019',
  format: 'iife',
  define: { 'process.env.NODE_ENV': '"production"' },
  legalComments: 'external',
  metafile: true,
  plugins: [{
    name: 'local-upstream-assets',
    setup(builder) {
      builder.onLoad({ filter: /[/\\]App\.jsx$/ }, async ({ path: filename }) => {
        // Preserve the upstream visuals and use local assets. Loop continuity
        // is handled in the source, independently of these URL substitutions.
        const contents = (await readFile(filename, 'utf8'))
          .replaceAll("imgPath: '/", "imgPath: '../img/gallery/")
          .replaceAll(
            'https://fonts.gstatic.com/s/sacramento/v5/buEzpo6gcdjy0EiZMBUG4C0f-w.woff',
            '../fonts/sacramento.woff'
          );
        return { contents, loader: 'jsx', resolveDir: path.dirname(filename) };
      });
    }
  }]
});

const outputs = Object.keys(result.metafile.outputs);
const javascript = path.basename(outputs.find(filename => filename.endsWith('.js')));
const stylesheet = path.basename(outputs.find(filename => filename.endsWith('.css')));
await writeFile(path.join(output, 'index.html'), `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="author" content="Cynthia Chiu">
  <title>3D Art Gallery — Cynthia Chiu</title>
  <link rel="icon" type="image/x-icon" sizes="16x16 32x32 48x48" href="../../favicon.ico?v=1">
  <link rel="icon" type="image/png" sizes="96x96" href="../img/favicon.png?v=1">
  <link rel="stylesheet" href="${stylesheet}">
</head>
<body>
  <!-- Original scene: https://github.com/cynthiachiu/3D-Art-Gallery
       Commit: 1cb30b8ef245bd67c56f5a1a8b07dfadcc9655ca
       Artwork and original implementation by Cynthia Chiu.
       Loop continuity adapted for this site. -->
  <div id="root"></div>
  <noscript>This 3D gallery requires JavaScript.</noscript>
  <script src="${javascript}" defer></script>
</body>
</html>
`);

// Preserve full dependency licenses alongside the static bundle.
const packages = new Set();
for (const filename of Object.keys(result.metafile.inputs)) {
  const match = filename.match(/^(.*node_modules\/(?:@[^/]+\/)?[^/]+)\//);
  if (match) packages.add(match[1]);
}
const notices = [];
for (const packagePath of [...packages].sort()) {
  const absolutePath = path.resolve(directory, packagePath);
  const info = JSON.parse(await readFile(path.join(absolutePath, 'package.json'), 'utf8'));
  const licenseName = (await readdir(absolutePath)).find(name => /^licen[sc]e(?:\.(?:md|txt))?$/i.test(name));
  if (licenseName) {
    notices.push(`${info.name}@${info.version}\n${await readFile(path.join(absolutePath, licenseName), 'utf8')}`);
  }
}
await writeFile(path.join(output, 'THIRD_PARTY_LICENSES.txt'), notices.join('\n\n----------------------------------------\n\n'));
console.log(`Original gallery built: ${path.relative(directory, output)}/index.html`);
